'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
// var hasOwnProp = require( '@stdlib/assert/has-own-property' );
// var defineProperty = require( '@stdlib/utils/define-property' );
var copy = require( '@stdlib/array/base/copy' );
var assign = require( '@stdlib/object/assign' );


// MAIN //

/**
* Returns a shallow clone of a value.
*
* ## Notes
*
* -   For arrays, returns a new array with the same elements.
* -   For plain objects, returns a new object with the same own enumerable properties.
*
* @private
* @param {(Object|Array)} value - value to shallow clone
* @returns {(Object|Array)} shallow clone
*
* @example
* var obj = { 'a': 1, 'b': { 'c': 2 } };
* var out = shallowClone( obj );
* // returns { 'a': 1, 'b': { 'c': 2 } }
*
* var bool = ( obj === out );
* // returns false
*
* bool = ( obj.b === out.b );
* // returns true
*/
function shallowClone( value ) {
	if ( isArray( value ) ) {
		return copy( value );
	}

	/* BUG: (Prototype Pollution with own "__proto__"): important security bug. assign({}, value) is vulnerable to own "__proto__" keys.
	var out;
	out = {};
	if ( hasOwnProp( value, '__proto__' ) ) {
		defineProperty( out, '__proto__', {
			'configurable': true,
			'enumerable': true,
			'writable': true,
			'value': value[ '__proto__' ]
		});
	}
	return assign( out, value ); */
	return assign( {}, value );
}


// EXPORTS //

module.exports = shallowClone;
